mapper.select:
SELECT USER_EMAIL, TITLE, REG_DATE, READ_CNT, CONTENT
FROM PLANT_STORY
WHERE BOARD_NUM = #{boardNum}

mapper.update:
UPDATE PLANT_STORY
SET READ_CNT = READ_CNT + 1
WHERE BOARD_NUM = #{boardNum};

UPDATE PLANT_STORY
SET TITLE = #{title}, CONTENT = #{content}
WHERE BOARD_NUM = #{boardNum}

mapper.insert:
INSERT INTO LIKE_PLANT (
    BOARD_NUM
    , USER_EMAIL
) VALUES (
    #{boardNum}
    ,#{userEmail}
)

mapper.delete:
DELETE FROM LIKE_PLANT
WHERE BOARD_NUM = #{boardNum}
AND USER_EMAIL = #{userEmail}
